function quoteOrder(input) {
  // Validate input
  if (
    !input ||
    !Number.isInteger(input.subtotalCents) ||
    input.subtotalCents < 0 ||
    input.subtotalCents > 1000000 ||
    !['NONE', 'SAVE10'].includes(input.coupon) ||
    !['standard', 'express', 'pickup'].includes(input.delivery)
  ) {
    return { error: 'invalid_order' };
  }

  // Compute discounted subtotal
  const discountedCents =
    input.coupon === 'SAVE10'
      ? Math.floor(input.subtotalCents * 0.9)
      : input.subtotalCents;

  // Compute shipping based on discounted subtotal
  let shippingCents;
  if (input.delivery === 'pickup') {
    shippingCents = 0;
  } else if (input.delivery === 'express') {
    shippingCents = 1500;
  } else {
    // standard shipping
    shippingCents = discountedCents >= 5000 ? 0 : 600;
  }

  // Return result
  return {
    discountedCents,
    shippingCents,
    totalCents: discountedCents + shippingCents,
  };
}

